// Hook wrapper to ensure reliable unpipe across all destinations
function createReliableStreamWrapper(stream) {
  const destinations = new Set();

  // Hook the pipe method to track destinations
  const originalPipe = stream.pipe.bind(stream);
  stream.pipe = function(dest, options) {
    const result = originalPipe(dest, options);
    destinations.add(dest);
    return result;
  };

  // Hook the unpipe method to clear tracked destinations
  const originalUnpipe = stream.unpipe.bind(stream);
  stream.unpipe = function(dest) {
    if (dest) {
      destinations.delete(dest);
    } else {
      // Unpipe from all destinations
      for (const dest of destinations) {
        originalUnpipe(dest);
      }
      destinations.clear();
    }
    return stream;
  };

  stream.getDestinations = () => [...destinations];
  stream.removeAllDestinations = () => {
    stream.unpipe(); // Unpipe from all
  };

  return stream;
}

