    const filePath = path.join(__dirname, '..', 'sample.txt');

    let readStream = fs.createReadStream(filePath);

    // Wrap the stream with hook tracking
    readStream = createReliableStreamWrapper(readStream);

    // Use unpipe to ensure clean state before piping
