// src/stream-hook.js
const { unpipe } = require('unpipe');

function createHookedStream(stream) {
  const destinations = new Set();
  const hooks = {
    beforeUnpipe: [],
    afterUnpipe: [],
    onError: []
  };

  // Hook pipe to track destinations
  const originalPipe = stream.pipe.bind(stream);
  stream.pipe = function (dest, options) {
    destinations.add(dest);
    return originalPipe(dest, options);
  };

  // Hook unpipe to ensure all destinations are cleared
  const originalUnpipe = stream.unpipe.bind(stream);
  stream.unpipe = function (dest) {
    try {
      // Run before hooks
      for (const hook of hooks.beforeUnpipe) {
        hook(dest || 'all');
      }

      if (dest) {
        destinations.delete(dest);
        return originalUnpipe(dest);
      }

      // Unpipe from all tracked destinations
      for (const d of [...destinations]) {
        originalUnpipe(d);
      }
      destinations.clear();
      return stream;
    } catch (err) {
      for (const hook of hooks.onError) {
        hook(err);
      }
      throw err;
    } finally {
      // Run after hooks
      for (const hook of hooks.afterUnpipe) {
        hook(dest || 'all');
      }
    }
  };

  // Add hook registration methods
  stream.hookBeforeUnpipe = (fn) => {
    hooks.beforeUnpipe.push(fn);
    return stream;
  };

  stream.hookAfterUnpipe = (fn) => {
    hooks.afterUnpipe.push(fn);
    return stream;
  };

  stream.hookOnError = (fn) => {
    hooks.onError.push(fn);
    return stream;
  };

  // Reliable unpipe wrapper
  stream.ensureUnpiped = function () {
    destinations.clear();
    return unpipe(stream);
  };

  return stream;
}

module.exports = { createHookedStream };
